+    }
+
+    public int GetStockLevel(string warehouse, string sku)
+    {
+        warehouse = NormalizeWarehouse(warehouse);
+        sku = NormalizeSku(sku);
+
+        return _stockByWarehouse.TryGetValue(warehouse, out var stockBySku)
+            && stockBySku.TryGetValue(sku, out var quantity)
+                ? quantity
+                : 0;
+    }
+
+    public void AddStock(string sku, int quantity) => AddStock(DefaultWarehouse, sku, quantity);
+
+    public void AddStock(string warehouse, string sku, int quantity)
+    {
+        warehouse = NormalizeWarehouse(warehouse);
+        sku = NormalizeSku(sku);
+        EnsurePositiveQuantity(quantity);
+
+        if (!_stockByWarehouse.TryGetValue(warehouse, out var stockBySku))
+        {
+            stockBySku = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+            _stockByWarehouse[warehouse] = stockBySku;
+        }
+
+        stockBySku[sku] = GetStockLevel(warehouse, sku) + quantity;
+    }
+
+    public void TransferStock(string sku, string sourceWarehouse, string destinationWarehouse, int quantity)
+    {
+        sku = NormalizeSku(sku);
+        sourceWarehouse = NormalizeWarehouse(sourceWarehouse);
+        destinationWarehouse = NormalizeWarehouse(destinationWarehouse);
+        EnsurePositiveQuantity(quantity);
+
+        if (string.Equals(sourceWarehouse, destinationWarehouse, StringComparison.OrdinalIgnoreCase))
+        {
+            throw new ArgumentException("Source and destination warehouses must be different.", nameof(destinationWarehouse));
+        }
