+    private readonly Dictionary<(string Warehouse, string Sku), int> _stockLevels = new();
+    private readonly int _reorderThreshold;
+
+    public InventoryTracker(int reorderThreshold = 10)
+    {
+        ArgumentOutOfRangeException.ThrowIfNegative(reorderThreshold);
+
+        _reorderThreshold = reorderThreshold;
+    }
+
+    public int GetStockLevel(string sku) => GetStockLevel(DefaultWarehouse, sku);
+
+    public int GetStockLevel(string warehouse, string sku)
+    {
+        var key = CreateKey(warehouse, sku);
+
+        return _stockLevels.GetValueOrDefault(key);
+    }
+
+    public void AddStock(string sku, int quantity) => AddStock(DefaultWarehouse, sku, quantity);
+
+    public void AddStock(string warehouse, string sku, int quantity)
+    {
+        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
+
+        var key = CreateKey(warehouse, sku);
+        _stockLevels[key] = checked(GetStockLevel(warehouse, sku) + quantity);
+    }
