+
+    public void TransferStock(string sourceWarehouse, string destinationWarehouse, string sku, int quantity)
+    {
+        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
+
+        var sourceKey = CreateKey(sourceWarehouse, sku);
+        var destinationKey = CreateKey(destinationWarehouse, sku);
+
+        if (sourceKey.Warehouse == destinationKey.Warehouse)
+        {
+            throw new ArgumentException("Source and destination warehouses must be different.", nameof(destinationWarehouse));
+        }
+
+        var sourceStock = GetStockLevel(sourceWarehouse, sku);
+        if (sourceStock < quantity)
