+            throw new InvalidOperationException("Insufficient stock for transfer.");
+        }
+
+        _stockLevels[sourceKey] = sourceStock - quantity;
+        _stockLevels[destinationKey] = checked(GetStockLevel(destinationWarehouse, sku) + quantity);
+    }
