+    private readonly int _reorderThreshold;
+
+    public InventoryTracker(int reorderThreshold = 10)
+    {
+        if (reorderThreshold < 0)
+        {
+            throw new ArgumentOutOfRangeException(nameof(reorderThreshold), "Reorder threshold cannot be negative.");
+        }
+
+        _reorderThreshold = reorderThreshold;
+    }
+
+    public int GetStockLevel(string sku)
+    {
+        ValidateRequired(sku, nameof(sku));
+
+        return _stockBySku.TryGetValue(sku, out var warehouseStock)
+            ? warehouseStock.Values.Sum()
+            : 0;
+    }
+
+    public int GetStockLevel(string sku, string warehouse)
+    {
+        ValidateRequired(sku, nameof(sku));
+        ValidateRequired(warehouse, nameof(warehouse));
+
+        return _stockBySku.TryGetValue(sku, out var warehouseStock)
+            && warehouseStock.TryGetValue(warehouse, out var quantity)
+            ? quantity
+            : 0;
+    }
+
+    public void AddStock(string sku, int quantity) => AddStock(sku, DefaultWarehouse, quantity);
+
+    public void AddStock(string sku, string warehouse, int quantity)
+    {
+        ValidateRequired(sku, nameof(sku));
+        ValidateRequired(warehouse, nameof(warehouse));
+        ValidatePositiveQuantity(quantity);
+
+        if (!_stockBySku.TryGetValue(sku, out var warehouseStock))
+        {
+            warehouseStock = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+            _stockBySku[sku] = warehouseStock;
+        }
+
+        warehouseStock[warehouse] = GetStockLevel(sku, warehouse) + quantity;
+    }
+
+    public bool NeedsReorder(string sku)
+    {
+        ValidateRequired(sku, nameof(sku));
+
+        return GetStockLevel(sku) <= _reorderThreshold;
+    }
+
+    public void TransferStock(string sku, string sourceWarehouse, string destinationWarehouse, int quantity)
+    {
+        ValidateRequired(sku, nameof(sku));
+        ValidateRequired(sourceWarehouse, nameof(sourceWarehouse));
+        ValidateRequired(destinationWarehouse, nameof(destinationWarehouse));
+        ValidatePositiveQuantity(quantity);
+
+        if (string.Equals(sourceWarehouse, destinationWarehouse, StringComparison.OrdinalIgnoreCase))
+        {
+            throw new ArgumentException("Source and destination warehouses must be different.", nameof(destinationWarehouse));
+        }
+
+        var availableStock = GetStockLevel(sku, sourceWarehouse);
+        if (availableStock < quantity)
+        {
+            throw new InvalidOperationException("Cannot transfer more stock than is available in the source warehouse.");
+        }
+
+        var warehouseStock = _stockBySku[sku];
+        warehouseStock[sourceWarehouse] = availableStock - quantity;
+        warehouseStock[destinationWarehouse] = GetStockLevel(sku, destinationWarehouse) + quantity;
+    }
+
+    private static void ValidatePositiveQuantity(int quantity)
+    {
+        if (quantity <= 0)
+        {
+            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");
+        }
+    }
+
+    private static void ValidateRequired(string value, string parameterName)
+    {
+        if (string.IsNullOrWhiteSpace(value))
+        {
